Input: {"question": "What is the profession of Ian Murray?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "start": 0, "end": 94, "text": "Ian Murray (Canadian politician) Ian Munro Murray (born May 7, 1951) is a Canadian politician."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "start": 95, "end": 191, "text": "He served in the House of Commons of Canada from 1993 to 2000, as a member of the Liberal Party."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "start": 192, "end": 316, "text": "Murray was born in Sarnia, Ontario, and received a Bachelor of Arts degree in History from the University of Guelph in 1973."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "start": 317, "end": 399, "text": "He had an extensive career in Canadian politics before running for office himself."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "start": 400, "end": 581, "text": "Murray was a research assistant for a Member of Parliament (MP) from 1974 to 1976, and a special assistant to the parliamentary secretary to the Minister of Communications from 1976"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0299-ee42d1f1bc01:d01", "start": 0, "end": 378, "text": "Party of Canada MPs Politicians from Sarnia 20th-century members of the House of Commons of Canada Hidden categories : Articles with short description Short description matches Wikidata Use Canadian English from September 2021 All Wikipedia articles written in Canadian English Use dmy dates from September 2021 This page was last edited on 14 December 2024 , at 02:33 ( UTC ) ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0299-ee42d1f1bc01:d01", "start": 379, "end": 489, "text": "Text is available under the Creative Commons Attribution-ShareAlike 4.0 License ; additional terms may apply ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0299-ee42d1f1bc01:d01", "start": 490, "end": 561, "text": "By using this site , you agree to the Terms of Use and Privacy Policy ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0299-ee42d1f1bc01:d01", "start": 562, "end": 601, "text": "Wikipedia® is a registered trademark of"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "start": 0, "end": 177, "text": "Ian Murray (bishop) Bishop Ian Murray (15 December 1932 – 22 January 2016), was a Scottish divine, the ninth Bishop of Argyll & the Isles after the restoration of the hierarchy."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "start": 178, "end": 283, "text": "Ian Murray was born in Lennoxtown as the eldest of the four children of John Murray and Margaret Rodgers."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "start": 284, "end": 454, "text": "He was educated at St Machan's Primary School, Lennoxtown, St Ninian's High School, Kirkintilloch and the National Junior Seminary at St Mary's College, Blairs, Aberdeen."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "start": 455, "end": 523, "text": "His Great Uncle, Paddy Murray, played for Hibernian FC and Scotland."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "start": 524, "end": 613, "text": "After Blairs, he completed his ecclesiastical studies at the Royal Scots College (el Real"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0299-ee42d1f1bc01:d03", "start": 0, "end": 676, "text": "Eric Alexander Joseph Alleine Richard Alleine Richard Allestree Isaac Ambrose James Anderson John Arrowsmith Bill Ascol Tom Ascol Simeon Ashe Robert Asty Aurelius Augustine St Augustine Greg Bahnsen Robert Baillie James Bannerman Matthew Barrett William Bates Nicholas T Batzig Voddie Baucham S M Baugh Herman Bavinck Richard Baxter G K Beale Greg Beale Joel R Beeke Alistair Begg E Calvin Beisner Richard Belcher William Benn Richard Bennett Louis Berkhof Theodore Beza Hugh Binning John Blanchard William Boekestein Loraine Boettner James Montgomery Boice Samuel Bolton Horatius Bonar Brian Borgman Thomas Boston James P Boyce Wilhelmus a Brakel William Bridge Jerry Bridges"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0299-ee42d1f1bc01:d04", "start": 0, "end": 207, "text": "to the Diocese of Argyll & the Isles Welcome Message from Bishop Brian McGee Welcome Message from Bishop Brian McGee Welcome to the website of the Diocese of Argyll & the Isles , and thank you for visiting ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0299-ee42d1f1bc01:d04", "start": 208, "end": 400, "text": "I hope you will enjoy exploring the contents of the site , learning about our Cathedral and parishes , our Led by the Spirit discernment process , our Celtic spiritual heritage and much more ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0299-ee42d1f1bc01:d04", "start": 401, "end": 497, "text": "It is a large diocese , taking in much of the western part of the Scottish Highlands & Islands ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0299-ee42d1f1bc01:d04", "start": 498, "end": 531, "text": "It covers over 31 thousand square"}}, "original_cards": [{"doc_id": "ramdocs-0299-ee42d1f1bc01:d00", "card_id": "ramdocs-0299-ee42d1f1bc01:d00:c0", "entity": "Ian Murray", "scope": "Profession", "claim": "Ian Munro Murray is a Canadian politician.", "answer": "Canadian politician", "quote": "Ian Murray (Canadian politician) Ian Munro Murray (born May 7, 1951) is a Canadian politician.", "original_document_number": 1}, {"doc_id": "ramdocs-0299-ee42d1f1bc01:d02", "card_id": "ramdocs-0299-ee42d1f1bc01:d02:c0", "entity": "Ian Murray", "scope": "profession", "claim": "Ian Murray was a Scottish divine, the ninth Bishop of Argyll & the Isles after the restoration of the hierarchy.", "answer": "Scottish divine", "quote": "Ian Murray (bishop) Bishop Ian Murray (15 December 1932 – 22 January 2016), was a Scottish divine, the ninth Bishop of Argyll & the Isles after the restoration of the hierarchy.", "original_document_number": 3}], "current_answers": ["Canadian politician", "Scottish divine"], "candidate_answers": [{"candidate_id": "R0", "answer": "Canadian politician", "origin": "initial"}, {"candidate_id": "R1", "answer": "Scottish divine", "origin": "initial"}]}

